/**
 * @method
 * @name sum
 * @description sum 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sum = async function (obj) {
    scwin.checkNumFormat(obj, 0);
    const one = obj.value;
    const two = $('input[name="pubofrAmt"]').val();
    const ones = one.replace(/,/gi, '');
    const twos = two.replace(/,/gi, '');
    if (ones.length > 15) {
        await $c.win.alert("상장수량(예정)의 입력값이 너무 큽니다.");
        return false;
    }
    if (ones === 0 || twos === 0) {
        $('input[name="listAmt"]').val(0);
    } else {
        const total = Number(ones) * Number(twos);
        const totals = String(total);
        if (totals.length > 18) {
            await $c.win.alert("상장총액(예정)의 입력값이 너무 큽니다. \n\n 상장수량(예정) * 공모가액(예정) = 상장총액(예정) ");
            $('input[name="listAmt"]').val('');
            return false;
        } else {
            $('input[name="listAmt"]').val(total);
        }
    }
    scwin.insertComma(1);
};

