/**
 * @method
 * @name mmCheck
 * @description mm Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mmCheck = async function () {
    let dayCnt = 0;
    for (let z = 0; z <= 12; z++) {
        if (z === 1) {
            if (($c.util.getComponent('slc_distrPayBasM').getValue() == null ? '' : String($c.util.getComponent('slc_distrPayBasM').getValue())) !== '' && ($c.util.getComponent('slc_distrPayBasD').getValue() == null ? '' : String($c.util.getComponent('slc_distrPayBasD').getValue())) !== '') {
                dayCnt++;
            }
        } else {
            if ($("select[name='distrPayBasM" + z + "']").val() !== '' && $("select[name='distrPayBasD" + z + "']").val() !== '') {
                dayCnt++;
            }
        }
    }
    for (let i = 1; i <= 12; i++) {
        if (i === 1) {
            let mm = $c.util.getComponent('slc_distrPayBasM').getValue();
            let dd = $c.util.getComponent('slc_distrPayBasD').getValue();
            let mmdd = mm + dd;
            $c.util.getComponent('ipt_distrPayBasDd').setValue(mmdd);
            let cnt = $c.util.getComponent('ipt_distrPayBasDd').getValue().length;
            if (cnt < 4 && ($c.util.getComponent('ipt_distrPayBasDd').getValue() == null ? '' : String($c.util.getComponent('ipt_distrPayBasDd').getValue())) !== '') {
                await $c.win.alert("분배금지급 기준일" + i + "의 형식이 잘못되었습니다.");
                return false;
            } else {
                for (let e = 2; e <= 12; e++) {
                    mm = $("select[name='distrPayBasM" + e + "']").val();
                    dd = $("select[name='distrPayBasD" + e + "']").val();
                    mmdd = mm + dd;
                    $("input[name='distrPayBasDd" + e + "']").val(mmdd);
                    cnt = $("input[name='distrPayBasDd" + e + "']").val().length;
                    if (cnt <= 3 && $("input[name='distrPayBasDd" + e + "']").val() !== '') {
                        await $c.win.alert("분배금지급 기준일" + e + "의 형식이 잘못되었습니다.");
                        return false;
                    }
                }
            }
        } else {
            if (i <= dayCnt) {
                mm = $("select[name='distrPayBasM" + i + "']").val();
                dd = $("select[name='distrPayBasD" + i + "']").val();
                mmdd = mm + dd;
                $("input[name='distrPayBasDd" + i + "']").val(mmdd);
                cnt = $("input[name='distrPayBasDd" + i + "']").val().length;
                if (cnt <= 3 && $("input[name='distrPayBasDd" + i + "']").val() !== '') {
                    await $c.win.alert("분배금지급 기준일" + i + "의 형식이 잘못되었습니다.");
                    return false;
                } else {
                    if (i === 2) {
                        if (($c.util.getComponent('ipt_distrPayBasDd').getValue() == null ? '' : String($c.util.getComponent('ipt_distrPayBasDd').getValue())) === '') {
                            await $c.win.alert("분배금지급 기준일1 을 먼저 작성해주세요.");
                            return false;
                        }
                    } else {
                        const j = i - 1;
                        if ($("input[name='distrPayBasDd" + j + "']").val() === '') {
                            await $c.win.alert("분배금지급 기준일" + j + " 을 먼저 작성해주세요.");
                            return false;
                        }
                    }
                }
            } else {
                $("select[name='distrPayBasM" + i + "']").val('');
                $("select[name='distrPayBasD" + i + "']").val('');
                $("input[name='distrPayBasDd" + i + "']").val('');
            }
        }
    }
    return true;
};

/**
 * @method
 * @name distrPayBas
 * @description distr Pay Bas 처리
 * @returns {void}
 * @hidden N
 */
scwin.distrPayBas = function () {
    for (let i = 1; i <= 12; i++) {
        if (i === 1) {
            let mmdd = $c.util.getComponent('ipt_distrPayBasDd').getValue();
            let mm = mmdd.substring(0, 2);
            let dd = mmdd.substring(2, 4);
            void("mmdd==" + mmdd + "mm==" + mm + "dd==" + dd);
            $c.util.getComponent('slc_distrPayBasM').setValue(mm).prop("selected", true);
            $c.util.getComponent('slc_distrPayBasD').setValue(dd).prop("selected", true);
        } else {
            void(i);
            mmdd = $("input[name='distrPayBasDd" + i + "']").val();
            mm = mmdd.substring(0, 2);
            dd = mmdd.substring(2, 4);
            $("select[name='distrPayBasM" + i + "']").val(mm).prop("selected", true);
            $("select[name='distrPayBasD" + i + "']").val(dd).prop("selected", true);
        }
    }
};

