/**
 * @method
 * @name checkNumFormat
 * @description check Num Format 처리
 * @param {Object} obj 컴포넌트
 * @param {*} len len
 * @returns {void}
 * @hidden N
 */
scwin.checkNumFormat = function (obj, len) {

    /* 음수 부호를 받을 변수 */

    let pre = '';
    /* 소수점 이하 값을 받을 변수 */
    let aft = '';

    if(obj.value.length>0) {
        if(obj.value.charAt(0)==='-'){
            pre = '-';
        }
    }

    /* 소수점 입력인 경우 */
    if(obj.value.indexOf('.')>0){
        aft = obj.value.substring(obj.value.indexOf('.'));
    }

    /* 파라미터고 2자리인 경우 */
    if(arguments.length===2)
    /* 넘겨받은 파라미터 값만큼 소수점 자리수를 허용 */
    if(aft.replace(/[^\d]/g,'').length>len) aft = aft.replace(/[^\d]/g,'').substring(0,len);

    obj.value = pre+(String(obj.value.replace(/\..*|[^\d]/g,'')))+(aft===''?'':'.'+aft.replace(/[^\d]/g,''));

    (obj.value = $c.num.formatNumber(obj.value));
};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};
